#include "facts_data.hpp"

namespace nikos::facts::data {

const Fact kHistoryFacts[kFactsPerCategory] = {
    {"history-001", "Reklamacja sprzed 3700 lat", "W starożytnej Mezopotamii ktoś złożył reklamację. Na glinianej tabliczce skarżył się na dostawę kiepskiej miedzi."},
    {"history-002", "Miasto budowniczych piramid", "W Gizie odkryto miasto ludzi budujących piramidy. Mieli własne piekarnie i dostawali mięso do jedzenia."},
    {"history-003", "Bary w Pompejach", "W starożytnych Pompejach działały bary z gotowym jedzeniem. Posiłki podawano z wielkich naczyń wbudowanych w ladę."},
    {"history-004", "Zero u Majów", "Majowie zapisywali zero symbolem muszli. Ich system liczbowy opierał się na dwudziestkach."},
    {"history-005", "Rachunki Inków", "Inkowie prowadzili rachunki za pomocą sznurków. Węzły i kolory pomagały im zapisywać liczby."},
    {"history-006", "Wikingowie w Ameryce", "Wikingowie dotarli do Ameryki około 500 lat przed Kolumbem. W Kanadzie zachowały się ślady ich osady sprzed 1000 lat."},
    {"history-007", "Szlaki jedwabne", "Jedwabny Szlak nie był jedną drogą. Tworzyły go liczne szlaki handlowe między Azją a Europą."},
    {"history-008", "Rękopisy Timbuktu", "W afrykańskim Timbuktu przechowywano tysiące rękopisów. Uczeni pisali tam o astronomii, medycynie i matematyce."},
    {"history-009", "Samurajski łuk", "Samurajowie w Japonii walczyli nie tylko mieczami. Ważną bronią był też łuk, często używany podczas jazdy konnej."},
    {"history-010", "Kanały Tenochtitlán", "Miasto Azteków miało wiele kanałów zamiast ulic. Po Tenochtitlán pływano łodziami, a wodę pitną dostarczały akwedukty."},
    {"history-011", "Król Jadwiga", "Jadwigę koronowano w 1384 roku na króla Polski. Miała około 10 lat i została pełnoprawnym władcą."},
    {"history-012", "Sól Wieliczki i Bochni", "Kopalnie soli w Wieliczce i Bochni działały już w XIII wieku. Górnicy wyrzeźbili pod ziemią kaplice i posągi z soli."},
    {"history-013", "Konstytucja 3 maja", "Polska uchwaliła jedną z pierwszych nowoczesnych konstytucji. Konstytucja 3 maja z 1791 roku zniosła liberum veto."},
    {"history-014", "Polki przy urnach", "Polki uzyskały prawa wyborcze w 1918 roku. W pierwszym wybranym później Sejmie zasiadło osiem kobiet."},
    {"history-015", "Odbudowa Starego Miasta", "Warszawskie Stare Miasto odbudowano po II wojnie światowej. W 1944 roku zniszczono ponad 85% jego zabudowy."},
    {"history-016", "Wielki pożar Londynu", "Pożar Londynu z 1666 roku zaczął się w piekarni. Przez cztery dni zniszczył około 13 000 domów."},
    {"history-017", "Owca, kaczka i kogut", "W 1783 roku we Francji wysłano balonem owcę, kaczkę i koguta. Był to pokazowy lot braci Montgolfier przed pierwszym swobodnym lotem ludzi."},
    {"history-018", "Rok bez lata", "Rok 1816 nazwano rokiem bez lata. Erupcja wulkanu Tambora rok wcześniej ochłodziła klimat."},
    {"history-019", "Wielki smród Londynu", "W 1858 roku smród Tamizy zakłócał obrady brytyjskiego parlamentu. Londyn przyspieszył wtedy budowę kanalizacji."},
    {"history-020", "Wyścig na biegun południowy", "Pierwszym człowiekiem na biegunie południowym był Roald Amundsen. Dotarł tam w 1911 roku, miesiąc przed wyprawą Scotta."},
    {"history-021", "Kobiety na igrzyskach", "Na pierwszych nowożytnych igrzyskach nie startowały kobiety. Wystąpiły dopiero w Paryżu w 1900 roku."},
    {"history-022", "Dwa Noble Skłodowskiej-Curie", "Maria Skłodowska-Curie zdobyła dwie Nagrody Nobla. Jedną z fizyki w 1903 roku, drugą z chemii w 1911."},
    {"history-023", "Grypa hiszpanka", "Grypa zwana „hiszpanką” wcale nie musiała pochodzić z Hiszpanii. Tamtejsza prasa pisała o epidemii swobodniej niż w krajach wojny."},
    {"history-024", "Otwarcie Muru Berlińskiego", "Mur Berliński nie zniknął w noc swojego upadku. W 1989 roku otwarto przejścia, a rozbiórkę zaczęto później."},
    {"history-025", "Nelson Mandela", "Nelson Mandela wyszedł z więzienia po 27 latach. W 1994 roku został pierwszym demokratycznie wybranym prezydentem RPA."},
    {"history-026", "Pierwszy znany strajk", "Egipscy robotnicy strajkowali już ponad 3 000 lat temu. Domagali się zaległych racji zboża, którymi im płacono."},
    {"history-027", "Gliniana armia", "W Chinach w 1974 roku odkryto armię z glinianych żołnierzy. Tysiące figur miało strzec grobowca pierwszego cesarza Chin."},
    {"history-028", "Planszówka sprzed 4500 lat", "W Mezopotamii grano w Królewską Grę z Ur już około 4500 lat temu. Zachowana tabliczka z regułami pochodzi jednak z dużo późniejszego okresu."},
    {"history-029", "Biblioteka króla Asyrii", "Król Asyrii Aszurbanipal zebrał bibliotekę glinianych tabliczek. Zachowały się w niej między innymi opowieści o Gilgameszu."},
    {"history-030", "Purpura ze ślimaków", "Dawniej cenny purpurowy barwnik uzyskiwano ze ślimaków morskich. Fenicjanie sprzedawali nim barwione tkaniny za wysoką cenę."},
    {"history-031", "Wielki Mur Chiński", "Wielki Mur Chiński powstawał przez wiele stuleci. Jego różne odcinki budowano za panowania różnych dynastii."},
    {"history-032", "Kamienne miasto Afryki", "W południowej Afryce, w dzisiejszym Zimbabwe, zbudowano kamienne miasto. Mury Wielkiego Zimbabwe powstały bez użycia zaprawy."},
    {"history-033", "Kamienne twarze", "Na wieżach świątyni Bayon w Kambodży wyrzeźbiono twarze. Kamienne oblicza spoglądają w różne strony."},
    {"history-034", "Pieniądze z papieru", "W Chinach papierowe pieniądze pojawiły się już w średniowieczu. Już w XI wieku państwo dynastii Song zaczęło je wydawać."},
    {"history-035", "Złoto Mansy Musy", "W XIV wieku Mansa Musa, władca Mali, odbył bogatą pielgrzymkę do Mekki. Kronikarze opisywali ogromne ilości złota, które rozdawał po drodze."},
    {"history-036", "Kraków na pierwszej liście UNESCO", "Kraków wpisano na pierwszą listę zabytków UNESCO w 1978 roku. Na całym świecie znalazło się na niej tylko 12 miejsc."},
    {"history-037", "Zamek w Malborku", "Zamek w Malborku jest ogromną średniowieczną budowlą z cegły. Krzyżacy rozbudowywali go od XIII wieku."},
    {"history-038", "Kopernik i jego książka", "Kopernik opisał Ziemię krążącą wokół Słońca. Jego książka ukazała się w 1543 roku, w roku jego śmierci."},
    {"history-039", "Polacy i Enigma", "Polscy matematycy złamali szyfr maszyny Enigma przed wojną. Dokonali tego w 1932 roku, a potem przekazali wiedzę aliantom."},
    {"history-040", "Niedźwiedź Wojtek", "Niedźwiedź Wojtek towarzyszył polskim żołnierzom podczas wojny. Według relacji pomagał przenosić amunicję pod Monte Cassino."},
    {"history-041", "Podróż Magellana", "Magellan nie ukończył pierwszej wyprawy dookoła Ziemi. Zginął na Filipinach, a statek do Europy doprowadził Elcano."},
    {"history-042", "Wyprawa Shackletona", "Statek Shackletona zatonął w lodach Antarktydy. Cała jego 28-osobowa załoga przeżyła dzięki akcji ratunkowej."},
    {"history-043", "Amelia nad Atlantykiem", "Amelia Earhart sama przeleciała nad Atlantykiem w 1932 roku. Była pierwszą kobietą, która dokonała tego bez międzylądowania."},
    {"history-044", "Zakup Luizjany", "W 1803 roku Stany Zjednoczone kupiły od Francji ogromny obszar. Zakup Luizjany niemal podwoił terytorium USA."},
    {"history-045", "Statua Wolności w częściach", "Statua Wolności przybyła z Francji do Nowego Jorku w częściach. Złożono ją ponownie na wyspie dopiero w 1886 roku."},
    {"history-046", "Głos kobiet", "W 1893 roku kobiety w Nowej Zelandii zdobyły prawo głosu. Był to pierwszy samorządny kraj z takim prawem wyborczym."},
    {"history-047", "Rosa Parks", "W 1955 roku czarnoskóra Rosa Parks odmówiła ustąpienia miejsca białemu pasażerowi. Jej aresztowanie wywołało bojkot segregacji w autobusach."},
    {"history-048", "21 postulatów", "W 1980 roku strajkujący w Gdańsku spisali 21 postulatów. Żądali między innymi wolnych związków zawodowych."},
    {"history-049", "Rok Afryki", "Rok 1960 nazwano Rokiem Afryki. Wiele państw kontynentu uzyskało wtedy niepodległość."},
    {"history-050", "Nastolatek wynalazca", "Pismo dla niewidomych opracował piętnastoletni Louis Braille. Z sześciu wypukłych punktów układa się w nim litery i cyfry."},
    {"history-051", "Pismo klinowe", "Pismo klinowe powstało w Mezopotamii ponad pięć tysięcy lat temu. Najpierw służyło między innymi zapisom gospodarczym."},
    {"history-052", "Hammurabi i prawo", "Zbiór praw Hammurabiego wyryto na kamiennej steli. Nie był najstarszym znanym zbiorem praw."},
    {"history-053", "Miasto Çatalhöyük", "Çatalhöyük istniało na obszarze dzisiejszej Turcji tysiące lat temu. Domy sąsiadowały tam bez typowych ulic."},
    {"history-054", "Göbekli Tepe", "Kamienne kręgi Göbekli Tepe powstały przed wynalezieniem pisma. Ich dokładna funkcja nadal jest badana."},
    {"history-055", "Kamień z Rosetty", "Kamień z Rosetty zawiera tekst w trzech zapisach. Pomógł badaczom odczytać egipskie hieroglify."},
    {"history-056", "Biblioteka Aleksandryjska", "Biblioteka Aleksandryjska była wielkim ośrodkiem nauki starożytności. Jej zbiory zanikały w złożonym procesie."},
    {"history-057", "Kalendarz juliański", "Juliusz Cezar wprowadził kalendarz juliański w 45 roku p.n.e. Zastąpił wcześniejszy rzymski system."},
    {"history-058", "Kalendarz gregoriański", "Reforma kalendarza z 1582 roku skorygowała narastający błąd dat. Nie wszystkie państwa przyjęły ją od razu."},
    {"history-059", "Narodziny islamu", "Islam ukształtował się w VII wieku na Półwyspie Arabskim. Jego historia wiąże się z działalnością Mahometa."},
    {"history-060", "Sobór w Nicei", "W 325 roku w Nicei zebrał się sobór biskupów chrześcijańskich. Odegrał ważną rolę w sporach o naturę Chrystusa i kształtowaniu doktryny."},
    {"history-061", "Zwoje znad Morza Martwego", "Zwoje znad Morza Martwego zawierają starożytne teksty żydowskie. Znaleziono je w XX wieku w rejonie Kumran."},
    {"history-062", "Religie starożytnego Egiptu", "Egipcjanie czcili liczne bóstwa, a praktyki zmieniały się przez stulecia. Ważną rolę odgrywały rytuały pogrzebowe."},
    {"history-063", "Zaratusztrianizm", "Zaratusztrianizm należy do najstarszych nadal praktykowanych religii. Jego dzieje wiążą się ze starożytnym Iranem."},
    {"history-064", "Świątynie Angkoru", "Angkor Wat zbudowano pierwotnie jako świątynię hinduistyczną. Później stał się ważnym miejscem buddyjskim."},
    {"history-065", "Buddyzm na Jedwabnym Szlaku", "Buddyzm rozprzestrzeniał się między Indiami a Azją Wschodnią szlakami handlowymi. Podróżowali nimi także mnisi."},
    {"history-066", "Starożytna matematyka Indii", "Indyjscy matematycy odegrali wielką rolę w rozwoju zapisu pozycyjnego. Symbol zera stał się jego częścią."},
    {"history-067", "Druk ruchomą czcionką", "W Chinach stosowano ruchomą czcionkę przed Gutenbergiem. Europejski druk rozwinął się później inną drogą."},
    {"history-068", "Kobiety w średniowiecznej nauce", "Hildegarda z Bingen pisała o muzyce, przyrodzie i medycynie. Była również przeoryszą i kompozytorką."},
    {"history-069", "Mapa Piri Reisa", "W 1513 roku osmański kartograf Piri Reis sporządził mapę części Atlantyku. Wykorzystał informacje z wcześniejszych map i relacji żeglarzy."},
    {"history-070", "Początki szczepień", "Edward Jenner badał szczepienie przeciw ospie prawdziwej w 1796 roku. Metody wariolizacji były znane wcześniej."},
    {"history-071", "Zakaz handlu niewolnikami", "W 1807 roku brytyjski parlament zakazał handlu niewolnikami w imperium. Nie oznaczało to natychmiastowego końca niewolnictwa."},
    {"history-072", "Haiti i niepodległość", "Haiti ogłosiło niepodległość w 1804 roku po rewolucji. Było to przełomowe zwycięstwo ludzi wyzwalających się z niewoli."},
    {"history-073", "Antarktyczny traktat", "Traktat antarktyczny podpisano w 1959 roku. Ustanowił ramy pokojowej współpracy i badań naukowych."},
    {"history-074", "Pierwszy sztuczny satelita", "Sputnik 1 wystartował w 1957 roku. Rozpoczął epokę sztucznych satelitów Ziemi."},
    {"history-075", "Rękopisy dostępne na ekranie", "Biblioteki cyfrowe udostępniają skany rękopisów, których oryginały pozostają w archiwach. Badacze mogą porównywać dokumenty bez podróżowania."},
    {"history-076", "Pierwsze miasta Mezopotamii", "Uruk należało do najwcześniejszych wielkich miast świata. Rozwijało się tysiące lat przed naszą erą."},
    {"history-077", "Jak powstały monety", "Jedne z najwcześniejszych monet bito w Lidii w VII wieku p.n.e. Z czasem upowszechniły się w innych regionach."},
    {"history-078", "Drogi Imperium Rzymskiego", "Rzymianie budowali rozległą sieć dróg utwardzanych kamieniem. Ułatwiały ruch armii, ludzi i towarów."},
    {"history-079", "Papier z Chin", "W Chinach rozwijano wytwarzanie papieru już w starożytności. Technologia stopniowo dotarła do innych części świata."},
    {"history-080", "Nawigacja z gwiazd", "Żeglarze Polinezji wykorzystywali gwiazdy, fale i ptaki. W ten sposób pokonywali ogromne odległości oceanu."},
    {"history-081", "Władczyni Hatshepsut", "Hatszepsut rządziła Egiptem jako faraon. W przedstawieniach królewskich nosiła również tradycyjne insygnia władcy."},
    {"history-082", "Dawny alfabet fenicki", "Fenicki system pisma zapisywał przede wszystkim spółgłoski. Wpłynął na rozwój między innymi alfabetu greckiego."},
    {"history-083", "Wikingowie i handel", "Wikingowie docierali szlakami rzecznymi aż ku Morzu Czarnemu. Zajmowali się również dalekosiężnym handlem."},
    {"history-084", "Wspólne średniowieczne miasto", "W Kordobie epoki kalifatu żyli muzułmanie, chrześcijanie i Żydzi. Ich sytuacja prawna i wzajemne relacje zmieniały się w czasie."},
    {"history-085", "Kiedy wynaleziono okulary", "Okulary do czytania pojawiły się w Europie pod koniec XIII wieku. Z czasem zaczęto wytwarzać soczewki do różnych potrzeb."},
    {"history-086", "Jak dawniej rysowano świat", "Dawni kartografowie tworzyli mapy zarówno na podstawie podróży, jak i odziedziczonych opisów. Dlatego obok prawdziwych lądów umieszczali krainy wyobrażone."},
    {"history-087", "Narodziny drukowanej prasy", "Na początku XVII wieku w Europie zaczęły ukazywać się regularne drukowane gazety. Rozwój poczty pomagał rozpowszechniać wiadomości."},
    {"history-088", "Rewolucja cukrowa", "Rozwój plantacji cukru był związany z przymusową pracą i niewolnictwem. Cukier stał się ważnym towarem handlu atlantyckiego."},
    {"history-089", "Kobiety na uniwersytetach", "Przez stulecia wiele uczelni ograniczało kobietom dostęp do studiów. Zmiany zachodziły stopniowo i nierówno w różnych krajach."},
    {"history-090", "Jak mierzyli czas", "W wielu dawnych miastach używano zegarów słonecznych i wodnych. Pomagały organizować życie codzienne i rytuały."},
    {"history-091", "Mapa cholery Londynu", "John Snow naniósł przypadki cholery na mapę dzielnicy Soho. Jego badania pomogły wskazać skażoną wodę jako drogę zakażenia."},
    {"history-092", "Ziemia z rakiety", "W 1946 roku rakieta V-2 wykonała zdjęcia Ziemi z dużej wysokości. Stało się to przed wystrzeleniem pierwszego satelity."},
    {"history-093", "Radiowe wiadomości", "Na początku XX wieku radio pozwoliło przekazywać wiadomości na duże odległości. Zmieniło żeglugę i komunikację publiczną."},
    {"history-094", "Kobiety w programie Apollo", "W programie Apollo pracowały również matematyczki i informatyczki. Ich obliczenia pomagały planować misje kosmiczne."},
    {"history-095", "Odkrycie insuliny", "W latach 20. XX wieku opracowano leczenie cukrzycy insuliną. Stało się to przełomem w medycynie."},
    {"history-096", "Pierwszy lot braci Wright", "W 1903 roku bracia Wright wykonali kontrolowany lot samolotem z napędem. Ich maszyna utrzymywała się w powietrzu przez kilkanaście sekund."},
    {"history-097", "Dawne drogi soli", "Sól była cennym towarem długo przed rewolucją przemysłową. Transportowano ją szlakami handlowymi na duże odległości."},
    {"history-098", "Pismo z Wyspy Wielkanocnej", "Na Rapa Nui zachowały się tabliczki ze znakami rongorongo. Ich odczytanie pozostaje przedmiotem sporów."},
    {"history-099", "Zapisane głosy przeszłości", "Archiwa dźwiękowe przechowują nagrania sprzed ponad wieku. Pozwalają badać dawne języki, muzykę i wymowę."},
    {"history-100", "Kiedy pojawiły się muzea", "Publiczne kolekcje i muzea rozwijały się w Europie w epoce nowożytnej. Wcześniej cenne zbiory często były prywatne."},
};

}  // namespace nikos::facts::data
